/* Local indicative valuation rules, never transaction prices or measurement-error tolerances. */
const BusinessRulesModel={
 policyFields:['weightKg','shortfallKg','rate','unit','comparison','enabled'],
 selectors:['speciesId','breedId','sexId'],
 seed(sales={}){return {version:1,global:{weightKg:sales.weight??35,shortfallKg:sales.margin??0,rate:sales.rate??450,unit:'INR/kg',comparison:sales.comparison??'>',enabled:true},overrides:[]};},
 migrateLegacy(sales,legacy,registry){let model=this.seed(sales);if(!legacy)return model;if(!Array.isArray(legacy.rows))throw Error('Legacy group rules are invalid; review the saved policy.');const find=(kind,value,parent)=>{if(!value)throw Error('Legacy '+kind+' is missing.');const normalized=String(value).trim().toLowerCase(),matches=EntityRegistryModel.rows(registry,kind).filter(r=>r.active&&(!parent||r.parentId===parent)&&(r.id===value||r.name.toLowerCase()===normalized));if(matches.length!==1)throw Error('Cannot migrate legacy '+kind+' "'+value+'": choose a matching active record.');return matches[0].id;};for(const [index,row] of legacy.rows.entries()){const speciesId=find('species',row.species),breedId=String(row.breed||'').trim().toLowerCase()==='any breed'?'':find('breeds',row.breed,speciesId),sexId=find('sex_values',row.sex);model=this.upsert(model,{id:'legacy-sales-group-'+index,speciesId,breedId,sexId,enabled:row.enabled!==false,active:true,weightKg:row.minWeight??legacy.minWeight??model.global.weightKg,shortfallKg:legacy.tolerance??model.global.shortfallKg,comparison:'>=',rate:row.price??model.global.rate,unit:'INR/kg'},registry);}model.legacySource=structuredClone(legacy);model.shareWeighing=legacy.shareWeighing!==false;return model;},
 number(value,label){if(value===null||value===undefined||typeof value==='boolean'||String(value).trim()===''||!Number.isFinite(Number(value)))throw Error(label+' must be a finite number.');return Number(value);},
 toKg(value,unit='kg'){const number=this.number(value,'Weight');if(!['kg','g'].includes(unit))throw Error('Use kg or g.');if(number<0)throw Error('Weight cannot be negative.');const kg=unit==='g'?number/1000:number;if(!Number.isFinite(kg)||kg>Number.MAX_SAFE_INTEGER/1000)throw Error('Weight is outside the supported range.');return kg;},
 specificity(row){return this.selectors.filter(key=>row[key]).length;},
 overlaps(a,b){return this.selectors.every(key=>!a[key]||!b[key]||a[key]===b[key]);},
 policyErrors(rule){const errors=[];for(const key of ['weightKg','shortfallKg','rate']){try{this.number(rule[key],key);}catch(e){errors.push(e.message);}}if(errors.length)return errors;const weight=Number(rule.weightKg),shortfall=Number(rule.shortfallKg),rate=Number(rule.rate);if(weight<=0)errors.push('Minimum weight must be positive.');if(shortfall<0||shortfall>=weight)errors.push('Allowable shortfall must be zero or greater and below minimum weight.');if(shortfall>1)errors.push('Allowable shortfall cannot exceed 1 kg (1,000 g), the existing reporting limit.');if(rate<=0)errors.push('Indicative valuation rate must be positive.');if(weight>Number.MAX_SAFE_INTEGER/1000||rate>Number.MAX_SAFE_INTEGER)errors.push('Weight or rate is outside the supported range.');if(!['INR/kg','INR/animal'].includes(rule.unit))errors.push('Choose INR/kg or INR/animal.');if(!['>','>='].includes(rule.comparison))errors.push('Choose > or >= for weight eligibility.');if(typeof rule.enabled!=='boolean')errors.push('Eligibility enabled must be true or false.');return errors;},
 references(row,registry){const errors=[];for(const [key,kind] of [['speciesId','species'],['breedId','breeds'],['sexId','sex_values']]){if(!row[key])continue;const ref=EntityRegistryModel.rows(registry,kind).find(r=>r.id===row[key]&&r.active);if(!ref)errors.push('Choose an active '+EntityRegistryModel.def(kind).singular+'.');if(key==='breedId'&&ref&&(!row.speciesId||ref.parentId!==row.speciesId))errors.push('Breed must belong to the selected animal type.');}return errors;},
 effective(model,row){const rule={...model.global};for(const key of this.policyFields)if(row&&row[key]!==undefined&&row[key]!==null&&row[key]!=='')rule[key]=row[key];for(const key of ['weightKg','shortfallKg','rate'])rule[key]=Number(rule[key]);return rule;},
 validate(model,registry){if(!model||!model.global||!Array.isArray(model.overrides))return ['Invalid business rules document.'];const errors=this.policyErrors(model.global),ids=new Set();for(const row of model.overrides){if(!row.id||ids.has(row.id))errors.push('Override IDs must be present and unique.');ids.add(row.id);if(row.active===false)continue;if(!this.specificity(row))errors.push('Choose an animal type, breed or sex for each override.');errors.push(...this.references(row,registry));errors.push(...this.policyErrors(this.effective(model,row)));}const rows=model.overrides.filter(r=>r.active!==false);for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++)if(this.specificity(rows[i])===this.specificity(rows[j])&&this.overlaps(rows[i],rows[j]))errors.push('Ambiguous overrides: '+rows[i].id+' and '+rows[j].id+' match the same animals at equal specificity.');return [...new Set(errors)];},
 upsert(model,input,registry){const next=structuredClone(model),id=input.id||crypto.randomUUID(),existing=next.overrides.find(r=>r.id===id),row={id,active:input.active??existing?.active??true,...Object.fromEntries(this.selectors.map(k=>[k,String(input[k]??existing?.[k]??'').trim()]))};for(const key of this.policyFields){const value=input[key]!==undefined?input[key]:existing?.[key];if(value!==undefined&&value!==null&&value!=='')row[key]=['weightKg','shortfallKg','rate'].includes(key)?this.number(value,key):value;}if(existing)next.overrides[next.overrides.indexOf(existing)]=row;else next.overrides.push(row);const errors=this.validate(next,registry);if(errors.length)throw Error(errors.join(' '));next.version=(model.version||0)+1;return next;},
 archive(model,id){const next=structuredClone(model),row=next.overrides.find(r=>r.id===id);if(!row)throw Error('Override not found.');row.active=false;next.version=(model.version||0)+1;return next;},
 resolve(model,animal,registry){const errors=this.validate(model,registry);errors.push(...this.references(animal,registry));if(errors.length)throw Error(errors.join(' '));const matches=model.overrides.filter(r=>r.active!==false&&this.selectors.every(k=>!r[k]||r[k]===animal[k])).sort((a,b)=>this.specificity(b)-this.specificity(a));const winner=matches[0];return {rule:this.effective(model,winner),overrideId:winner?.id||null,specificity:winner?this.specificity(winner):0};},
 evaluate(model,animal,registry){const resolved=this.resolve(model,animal,registry),weightKg=this.toKg(animal.weight,animal.weightUnit||'kg'),rule=resolved.rule,effectiveThresholdKg=rule.weightKg-rule.shortfallKg;const eligible=rule.enabled&&(rule.comparison==='>'?weightKg>effectiveThresholdKg:weightKg>=effectiveThresholdKg);const rawValuation=rule.unit==='INR/animal'?rule.rate:weightKg*rule.rate;if(!Number.isFinite(rawValuation)||rawValuation>Number.MAX_SAFE_INTEGER/100)throw Error('Indicative valuation exceeds the supported range.');return {...resolved,weightKg,effectiveThresholdKg,allowableShortfallKg:rule.shortfallKg,eligible,ready:eligible,saleBlocked:false,valuation:Math.round((rawValuation+Number.EPSILON)*100)/100,valuationUnit:rule.unit,valuationPurpose:'indicative',measurementErrorApplied:false};}
};
if(typeof globalThis!=='undefined')globalThis.BusinessRulesModel=BusinessRulesModel;
